import math

def sigma1(n):
    """Calculates the sum of divisors function sigma_1(n)."""
    s = 0
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            s += i
            j = n // i
            if i != j:
                s += j
    return s

def is_square(n):
    """Checks if n is a perfect square."""
    if n < 0:
        return False
    root = int(math.isqrt(n))
    return root * root == n

candidate_m = []
for m in range(2, 51):
    sigma = sigma1(m)
    if is_square(sigma):
        candidate_m.append((m, sigma))

print(f"Candidates (m, sigma(m)): {candidate_m}")

import itertools
import math

def get_divisors(m):
    divs = set()
    for i in range(1, int(math.sqrt(m)) + 1):
        if m % i == 0:
            divs.add(i)
            divs.add(m // i)
    return sorted(list(divs))

def is_perfect_square(n):
    if n < 0:
        return False
    sqrt_n = int(math.isqrt(n))
    return sqrt_n * sqrt_n == n

def check_m(m):
    divisors = get_divisors(m)
    n = len(divisors)

    # Necessary condition: The sum of all divisors must be a perfect square.
    sigma_m = sum(divisors)
    if not is_perfect_square(sigma_m):
        # print(f"m={m}: Sigma({m}) = {sigma_m}. Not a perfect square. Skipping.")
        return False

    # Check all permutations
    for perm in itertools.permutations(divisors):
        current_sum = 0
        is_valid = True
        for i in range(n):
            current_sum += perm[i]
            if not is_perfect_square(current_sum):
                is_valid = False
                break

        if is_valid:
            # print(f"m={m} found a solution: {perm}")
            return True

    return False

solutions = []
for m in range(2, 13):
    if check_m(m):
        solutions.append(m)

print(f"Solutions found: {solutions}")

import math

def sum_of_divisors(n):
    """Calculates sigma_1(n), the sum of divisors of n."""
    if n <= 0:
        return 0

    s = 1
    temp = n
    i = 2
    while i * i <= temp:
        if temp % i == 0:
            p = i
            count = 0
            while temp % p == 0:
                count += 1
                temp //= p

            # Contribution of p^count to sigma_1(n) is (p^(count+1) - 1) / (p - 1)
            s *= (p**(count + 1) - 1) // (p - 1)
        i += 1

    if temp > 1:
        # Remaining temp is a prime factor
        s *= (temp**2 - 1) // (temp - 1) # = temp + 1

    return s

def is_perfect_square(n):
    if n < 0:
        return False
    sqrt_n = int(math.isqrt(n))
    return sqrt_n * sqrt_n == n

candidates = []
for m in range(51, 101):
    sigma = sum_of_divisors(m)
    if is_perfect_square(sigma):
        candidates.append(m)

