def sigma(n):
    s = 1
    temp = n
    i = 2
    while i * i <= temp:
        if temp % i == 0:
            count = 0
            while temp % i == 0:
                count += 1
                temp //= i
            s *= (i**(count + 1) - 1) // (i - 1)
        i += 1
    if temp > 1:
        s *= (temp**2 - 1) // (temp - 1)
    return s

